    if (date == null) {
        throw new IllegalArgumentException("Input date string cannot be null");
    }
    try {
        java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy");
        java.time.LocalDate localDate = java.time.LocalDate.parse(date.trim(), formatter);
        String monthName = localDate.getMonth()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        int day = localDate.getDayOfMonth();
        int year = localDate.getYear();
        String weekday = localDate.getDayOfWeek()
                .getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        return monthName + " " + day + ", " + year + " is a " + weekday;
    } catch (java.time.format.DateTimeParseException e) {
        throw new IllegalArgumentException("Invalid date format: " + date);
    }
}

