    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[low] <= nums[mid]) { // left side is sorted
            if (target >= nums[low] && target < nums[mid]) {
                high = mid - 1;
