    // Handle 0 separately
    if (startLow == 0) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int d = 1; d <= 9; d++) {
        if (d >= startLow && d <= high) {
            result.add(d);
        }
        queue.offer((long) d);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        int lastDigit = (int) (num % 10);
        // Next possible digits
        int[] nextDigits = {lastDigit - 1, lastDigit + 1};
        for (int nd : nextDigits) {
            if (nd < 0 || nd > 9) {
                continue;
