            long newNum = num * 10 + nd;
            if (newNum > high) {
                continue;
            }
            if (newNum >= startLow) {
                result.add((int) newNum);
            }
            queue.offer(newNum);
        }
    }
    Collections.sort(result);
    return result;
}

