public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 1;
    }
    int n = A.length;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    boolean[] used = new boolean[n];
    int[] result = new int[1];

    java.util.function.BiConsumer<Integer, Integer> backtrack = new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer depth, Integer lastIdx) {
            if (depth == n) {
                result[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                if (depth > 0) {
                    int sum = A[lastIdx] + A[i];
                    if (sum > maxSum || !isSquare[sum]) continue;
                }
                used[i] = true;
                accept(depth + 1, i);
                used[i] = false;
            }
        }
    };

    backtrack.accept(0, -1);
    return result[0];
}

